using System.Collections;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurgingEruptionAction", menuName = "Data/Battle/Battle Actions/Sothis/PurgingEruption Action")]
public class PurgingEruptionAction : BattleAction
{
	[Header("Apply Effect")]
	[SerializeField]
	private DefaultEffectAction effectAction;

	[SerializeField]
	private int effectAmount;

	[Header("Purified Lightning Action")]
	[SerializeField]
	private PurifiedLightningAction purifiedLightningAction;

	[Header("Description")]
	[SerializeField]
	private PurifyAction purifyAction;

	[Header("VFX")]
	[SerializeField]
	private float vfxDelay;

	public DefaultEffectAction EffectAction => effectAction;

	public int EffectAmount => effectAmount;

	public PurifyAction PurifyAction => purifyAction;

	public override void CastTargetAmount(GameObject target, int purifyAmount, GameObject source)
	{
		effectAction.CastTargetAmount(target, effectAmount, source);
		if (IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(VFXDelay(target, purifyAmount, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			int timesAmount = target.GetComponent<UnitEffects>().IsAfflictionActiveGetAmount();
			purifiedLightningAction.SingleTargetCastDefault(target, timesAmount, purifyAmount, source);
		}
	}

	private IEnumerator VFXDelay(GameObject target, int purifyAmount, GameObject source)
	{
		PlaySFXWithParameter("release", 0);
		GameObject vfx = GetVFX(GetVFXOwnerPosition(target));
		vfx.GetComponent<ParticleEmissionController>().SetActive(value: true);
		yield return new WaitForSeconds(vfxDelay);
		int timesAmount = target.GetComponent<UnitEffects>().IsAfflictionActiveGetAmount();
		purifiedLightningAction.SingleTargetCastDefault(target, timesAmount, purifyAmount, source, delegate
		{
			PlaySFX();
			SpawnSecondVFX(GetVFXOwnerPosition(target), 3f);
		}, null, delegate
		{
			SetSFXWithParameter("release", 1, release: true);
			vfx.GetComponent<ParticleEmissionController>().SetActive(value: false);
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(vfx, 3f);
		});
	}
}
